{
  "title": "Transformer 架构交互演示",
  "widget_type": "mockup",
  "loading_messages": ["正在构建计算图...", "加载注意力权重...", "初始化位置编码..."],
  "width": 780,
  "height": 580,
  "assistant_text": "这是一个交互式的 Transformer 架构图，点击各个组件可以查看其详细功能说明。"
}

<widget_code>
<style>
  :root {
    --panel-bg: var(--color-background-secondary);
    --card-bg: var(--color-background-primary);
  }

  .transformer-container {
    display: grid;
    grid-template-columns: 1fr 300px;
    gap: 16px;
    padding: 16px;
    font-family: var(--font-sans);
    color: var(--color-text-primary);
    height: 540px;
  }

  .diagram-view {
    background: var(--panel-bg);
    border-radius: var(--border-radius-lg);
    padding: 20px;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    position: relative;
  }

  .detail-panel {
    background: var(--card-bg);
    border: 0.5px solid var(--color-border-tertiary);
    border-radius: var(--border-radius-lg);
    padding: 20px;
    display: flex;
    flex-direction: column;
    gap: 12px;
  }

  .node {
    cursor: pointer;
    transition: transform 0.1s, filter 0.2s;
  }
  .node:hover {
    filter: brightness(0.95);
    transform: translateY(-1px);
  }
  .node:active {
    transform: translateY(0);
  }

  .label-tag {
    font-size: 12px;
    font-weight: 500;
    padding: 2px 8px;
    border-radius: 4px;
    margin-bottom: 4px;
    display: inline-block;
  }

  .formula {
    font-family: var(--font-serif);
    background: var(--color-background-tertiary);
    padding: 8px;
    border-radius: var(--border-radius-md);
    font-size: 14px;
    margin: 8px 0;
    border-left: 3px solid var(--color-border-info);
  }

  .badge {
    font-size: 11px;
    padding: 2px 6px;
    border-radius: 10px;
    text-transform: uppercase;
  }

  h3 { margin: 0; font-size: 18px; font-weight: 500; }
  p { margin: 0; font-size: 14px; line-height: 1.6; color: var(--color-text-secondary); }
</style>

<div class="transformer-container">
  <div class="diagram-view">
    <svg width="400" height="650" viewBox="0 0 400 650" fill="none" xmlns="http://www.w3.org/2000/svg">
      <!-- Arrows & Connections -->
      <path d="M100 580 V540" stroke="var(--color-border-primary)" stroke-width="2" marker-end="url(#arrowhead)"/>
      <path d="M300 580 V540" stroke="var(--color-border-primary)" stroke-width="2" marker-end="url(#arrowhead)"/>
      <path d="M100 480 V440" stroke="var(--color-border-primary)" stroke-width="2" marker-end="url(#arrowhead)"/>
      <path d="M300 480 V440" stroke="var(--color-border-primary)" stroke-width="2" marker-end="url(#arrowhead)"/>

      <!-- Encoder to Decoder Connection -->
      <path d="M100 180 H200 V280 H250" stroke="var(--color-border-info)" stroke-width="2" stroke-dasharray="4 2" marker-end="url(#arrowhead)"/>

      <!-- Inputs -->
      <g class="node" onclick="showDetail('input_emb')">
        <rect x="50" y="580" width="100" height="40" rx="8" class="c-gray" fill="var(--color-background-tertiary)" stroke="var(--color-border-tertiary)"/>
        <text x="100" y="605" text-anchor="middle" class="ts" style="fill:var(--color-text-primary)">输入嵌入</text>
      </g>
      <g class="node" onclick="showDetail('pos_enc')">
        <circle cx="150" cy="560" r="15" class="c-amber" fill="#FAEEDA" stroke="#BA7517"/>
        <text x="150" y="564" text-anchor="middle" style="font-size:10px; fill:#633806">+</text>
      </g>

      <!-- Encoder Block -->
      <rect x="30" y="100" width="140" height="380" rx="12" stroke="var(--color-border-secondary)" stroke-dasharray="5 5" fill="none"/>
      <text x="40" y="120" style="font-size:12px; fill:var(--color-text-tertiary)">编码器 (Nx)</text>

      <g class="node" onclick="showDetail('mha_enc')">
        <rect x="45" y="380" width="110" height="60" rx="8" class="c-purple" />
        <text x="100" y="410" text-anchor="middle" class="th" style="fill:#3C3489">多头注意力</text>
        <text x="100" y="425" text-anchor="middle" class="ts" style="fill:#534AB7; font-size:10px">Self-Attention</text>
      </g>

      <g class="node" onclick="showDetail('ffn')">
        <rect x="45" y="180" width="110" height="60" rx="8" class="c-purple" />
        <text x="100" y="215" text-anchor="middle" class="th" style="fill:#3C3489">前馈网络</text>
      </g>

      <!-- Decoder Block -->
      <rect x="230" y="100" width="140" height="380" rx="12" stroke="var(--color-border-secondary)" stroke-dasharray="5 5" fill="none"/>
      <text x="240" y="120" style="font-size:12px; fill:var(--color-text-tertiary)">解码器 (Nx)</text>

      <g class="node" onclick="showDetail('masked_mha')">
        <rect x="245" y="380" width="110" height="60" rx="8" class="c-teal" />
        <text x="300" y="410" text-anchor="middle" class="th" style="fill:#085041">掩码注意力</text>
        <text x="300" y="425" text-anchor="middle" class="ts" style="fill:#0F6E56; font-size:10px">Masked MHA</text>
      </g>

      <g class="node" onclick="showDetail('cross_mha')">
        <rect x="245" y="280" width="110" height="60" rx="8" class="c-teal" />
        <text x="300" y="310" text-anchor="middle" class="th" style="fill:#085041">交叉注意力</text>
        <text x="300" y="325" text-anchor="middle" class="ts" style="fill:#0F6E56; font-size:10px">Enc-Dec Attn</text>
      </g>

      <g class="node" onclick="showDetail('ffn')">
        <rect x="245" y="180" width="110" height="60" rx="8" class="c-teal" />
        <text x="300" y="215" text-anchor="middle" class="th" style="fill:#085041">前馈网络</text>
      </g>

      <!-- Output -->
      <g class="node" onclick="showDetail('output')">
        <rect x="245" y="20" width="110" height="40" rx="8" class="c-coral" />
        <text x="300" y="45" text-anchor="middle" class="th" style="fill:#712B13">线性 & Softmax</text>
      </g>
      <path d="M300 100 V60" stroke="var(--color-border-primary)" stroke-width="2" marker-end="url(#arrowhead)"/>

      <!-- Definitions -->
      <defs>
        <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="9" refY="3.5" orient="auto">
          <polygon points="0 0, 10 3.5, 0 7" fill="var(--color-border-primary)" />
        </marker>
      </defs>
    </svg>
  </div>

  <div class="detail-panel" id="detail-panel">
    <div id="empty-state" style="text-align: center; margin-top: 100px;">
      <div style="font-size: 40px; margin-bottom: 16px; opacity: 0.3;">🔍</div>
      <p>点击左侧架构图组件<br>查看详细原理解析</p>
    </div>
    <div id="content-state" style="display: none;">
      <span id="detail-tag" class="label-tag">组件类型</span>
      <h3 id="detail-title">组件名称</h3>
      <div id="detail-formula" class="formula"></div>
      <p id="detail-desc">详细描述内容...</p>
      <div style="margin-top: 16px; border-top: 0.5px solid var(--color-border-tertiary); padding-top: 16px;">
        <p style="font-size: 12px; font-weight: 500; color: var(--color-text-primary); margin-bottom: 8px;">关键特性：</p>
        <ul id="detail-features" style="font-size: 13px; color: var(--color-text-secondary); padding-left: 20px; margin: 0;">
        </ul>
      </div>
    </div>
  </div>
</div>

<script>
  const data = {
    input_emb: {
      title: "输入嵌入 (Input Embedding)",
      tag: "输入层",
      tagClass: "c-gray",
      formula: "Embedding(x) → Vector",
      desc: "将离散的单词（Token）转换为连续的低维稠密向量，捕捉单词间的语义关系。",
      features: ["词表映射", "维度固定 (d_model)", "语义对齐"]
    },
    pos_enc: {
      title: "位置编码 (Positional Encoding)",
      tag: "辅助层",
      tagClass: "c-amber",
      formula: "PE(pos, 2i) = sin(pos / 10000^(2i/d_model))",
      desc: "由于 Transformer 没有循环或卷积结构，无法感知顺序。位置编码通过正弦/余弦函数为每个 Token 注入位置信息。",
      features: ["绝对位置感知", "相对距离表达", "无需训练参数"]
    },
    mha_enc: {
      title: "多头自注意力 (Multi-Head Attention)",
      tag: "核心组件",
      tagClass: "c-purple",
      formula: "Attention(Q, K, V) = softmax(QKᵀ / √dₖ)V",
      desc: "允许模型在处理一个单词时，同时“关注”句子中其他位置的信息。多头机制让模型能从多个子空间学习不同的依赖关系。",
      features: ["并行计算", "长距离依赖建模", "全局感受野"]
    },
    masked_mha: {
      title: "掩码多头注意力 (Masked MHA)",
      tag: "解码组件",
      tagClass: "c-teal",
      formula: "Mask(QKᵀ) → -∞ for future tokens",
      desc: "在解码时，防止模型看到“未来”的信息。通过掩码机制，确保预测第 i 个单词时只能看到前 i-1 个单词。",
      features: ["自回归约束", "因果关系保护", "训练并行化"]
    },
    cross_mha: {
      title: "交叉注意力 (Encoder-Decoder Attention)",
      tag: "桥接组件",
      tagClass: "c-teal",
      formula: "Q from Decoder, K/V from Encoder",
      desc: "解码器通过此层访问编码器的输出。这使得解码器在生成目标单词时，能够参考输入序列的完整上下文。",
      features: ["源序列对齐", "跨模态/语言交互", "信息传递枢纽"]
    },
    ffn: {
      title: "前馈网络 (Feed Forward Network)",
      tag: "处理层",
      tagClass: "c-purple",
      formula: "FFN(x) = max(0, xW₁ + b₁)W₂ + b₂",
      desc: "对每个位置的向量进行独立的非线性变换。通常由两个线性层和一个 ReLU 激活函数组成。",
      features: ["逐位置处理", "特征维度扩张", "非线性增强"]
    },
    output: {
      title: "输出层 (Linear & Softmax)",
      tag: "输出层",
      tagClass: "c-coral",
      formula: "P = softmax(Linear(x))",
      desc: "将解码器的输出映射回词表大小的维度，并通过 Softmax 函数计算每个单词出现的概率分布。",
      features: ["概率预测", "词表映射", "贪婪/束搜索基础"]
    }
  };

  function showDetail(id) {
    const item = data[id];
    if (!item) return;

    document.getElementById('empty-state').style.display = 'none';
    document.getElementById('content-state').style.display = 'block';

    document.getElementById('detail-title').innerText = item.title;
    document.getElementById('detail-tag').innerText = item.tag;
    document.getElementById('detail-tag').className = 'label-tag ' + item.tagClass;
    document.getElementById('detail-formula').innerText = item.formula;
    document.getElementById('detail-desc').innerText = item.desc;

    const list = document.getElementById('detail-features');
    list.innerHTML = '';
    item.features.forEach(f => {
      const li = document.createElement('li');
      li.innerText = f;
      list.appendChild(li);
    });
  }
</script>
</widget_code>
